import{_ as a,o as l,c as t,ah as p}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"최종발표 대본 (1~9쪽)","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-28T00:00:00.000Z"},"headers":[{"level":2,"title":"1p 표지","slug":"_1p-표지","link":"#_1p-표지","children":[]},{"level":2,"title":"2p 목차","slug":"_2p-목차","link":"#_2p-목차","children":[]},{"level":2,"title":"3p 재난문자는 아이에게 너무 어려워요","slug":"_3p-재난문자는-아이에게-너무-어려워요","link":"#_3p-재난문자는-아이에게-너무-어려워요","children":[]},{"level":2,"title":"4p 어른도 헷갈리는 말이에요","slug":"_4p-어른도-헷갈리는-말이에요","link":"#_4p-어른도-헷갈리는-말이에요","children":[]},{"level":2,"title":"5p 이해, 행동, 연결이 모두 빠져 있어요","slug":"_5p-이해-행동-연결이-모두-빠져-있어요","link":"#_5p-이해-행동-연결이-모두-빠져-있어요","children":[]},{"level":2,"title":"6p 또리는 재난문자를 아이 눈높이로 바꿔요","slug":"_6p-또리는-재난문자를-아이-눈높이로-바꿔요","link":"#_6p-또리는-재난문자를-아이-눈높이로-바꿔요","children":[]},{"level":2,"title":"7p 아이 화면 (약 40초)","slug":"_7p-아이-화면-약-40초","link":"#_7p-아이-화면-약-40초","children":[]},{"level":2,"title":"8p 보호자 화면 (약 40초)","slug":"_8p-보호자-화면-약-40초","link":"#_8p-보호자-화면-약-40초","children":[]},{"level":2,"title":"9p 재난이 오기 전에 미리 익혀요 (약 40초)","slug":"_9p-재난이-오기-전에-미리-익혀요-약-40초","link":"#_9p-재난이-오기-전에-미리-익혀요-약-40초","children":[]},{"level":2,"title":"발표 자료를 고친 과정","slug":"발표-자료를-고친-과정","link":"#발표-자료를-고친-과정","children":[]},{"level":2,"title":"Q&A 대비","slug":"q-a-대비","link":"#q-a-대비","children":[]}],"relativePath":"computer/project/AWS-PBL/04. 최종발표 대본 (2026-11-28).md","filePath":"computer/project/AWS-PBL/04. 최종발표 대본 (2026-11-28).md"}'),r={name:"computer/project/AWS-PBL/04. 최종발표 대본 (2026-11-28).md"};function i(o,e,n,h,u,_){return l(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="최종발표-대본-1-9쪽" tabindex="-1">최종발표 대본 (1~9쪽) <a class="header-anchor" href="#최종발표-대본-1-9쪽" aria-label="Permalink to &quot;최종발표 대본 (1~9쪽)&quot;">​</a></h1><blockquote><p>AWS Career Launchpad PBL 또리(DDORI) 최종발표(2026-11-28 11:00). 전체 10분 중 시연 영상 2분, 실제 발표 8분. 내가 맡은 부분은 1쪽 표지부터 9쪽 서비스 화면까지(약 4분 30초). 근거 자료는 <a href="./03. 최종발표 문제 정의 근거 (2026-11-28).html">03. 최종발표 문제 정의 근거</a>.</p></blockquote><p>발표 자료 쪽 순서(16쪽): 표지, 목차, 재난문자는 아이에게 너무 어려워요, 어른도 헷갈리는 말이에요, 이해·행동·연결이 모두 빠져 있어요, 또리는 재난문자를 아이 눈높이로 바꿔요, 아이 화면, 보호자 화면, 재난이 오기 전에 미리 익혀요, 이후 기술 구성(10~13), 시연(14), 앞으로(15), Q&amp;A(16).</p><h2 id="_1p-표지" tabindex="-1">1p 표지 <a class="header-anchor" href="#_1p-표지" aria-label="Permalink to &quot;1p 표지&quot;">​</a></h2><p>안녕하십니까, 2팀 발표 시작하겠습니다.</p><p>저희가 만든 건 어린이를 위한 재난문자 도우미, 또리입니다.</p><p>이 친구가 또리의 &#39;또&#39;를 맡은 또또, 이 친구가 &#39;리&#39;를 맡은 리리입니다. 또또는 아이 곁에서, 리리는 보호자 곁에서 도와줍니다.</p><h2 id="_2p-목차" tabindex="-1">2p 목차 <a class="header-anchor" href="#_2p-목차" aria-label="Permalink to &quot;2p 목차&quot;">​</a></h2><p>우선 문제 정의, 이를 위한 해결 방법, 실제 구현한 서비스 화면, 세부적 기술 구성 이후에 시연 영상을 보여 드리겠습니다.</p><h2 id="_3p-재난문자는-아이에게-너무-어려워요" tabindex="-1">3p 재난문자는 아이에게 너무 어려워요 <a class="header-anchor" href="#_3p-재난문자는-아이에게-너무-어려워요" aria-label="Permalink to &quot;3p 재난문자는 아이에게 너무 어려워요&quot;">​</a></h2><p>실제 저희가 받는 재난문자에는 어려운 단어들이 너무 많습니다.</p><p>저지대, 권고 발효, 비상저감조치 등 성인이 봐도 단번에 이해하지 못하는 비일상적 단어들이 비상 상황에 등장하게 됩니다.</p><h2 id="_4p-어른도-헷갈리는-말이에요" tabindex="-1">4p 어른도 헷갈리는 말이에요 <a class="header-anchor" href="#_4p-어른도-헷갈리는-말이에요" aria-label="Permalink to &quot;4p 어른도 헷갈리는 말이에요&quot;">​</a></h2><p>특히 &#39;대피 권고&#39;는 어른들도 &#39;안 가도 되지만 가면 좋다&#39; 정도로 읽는 경우가 많습니다.</p><p>실제로 일본에서는 2019년 태풍 때 피난 권고가 나와도 대피하지 않은 사람이 많았는데, 조사해 보니 &#39;피난 권고&#39;와 &#39;피난 지시&#39;, 두 말의 뜻을 바르게 아는 어른이 10명 중에 2명 미만이었습니다.</p><p>그래서 일본에서는 &#39;피난 권고&#39;라는 말 자체를 법에서 없앴습니다.</p><p>어른도 헷갈리는 말을 아이는 더 이해하기 어렵습니다.</p><h2 id="_5p-이해-행동-연결이-모두-빠져-있어요" tabindex="-1">5p 이해, 행동, 연결이 모두 빠져 있어요 <a class="header-anchor" href="#_5p-이해-행동-연결이-모두-빠져-있어요" aria-label="Permalink to &quot;5p 이해, 행동, 연결이 모두 빠져 있어요&quot;">​</a></h2><p>결국 재난문자를 받은 아이에게는 세 가지가 빠져 있습니다.</p><p>재난문자가 와도 무슨 말인지, 이해하더라도 뭘 해야 할지 모르고, 하더라도 안전한지 알릴 방법이 없습니다.</p><p>그러다 보니 부모도 아이가 어디 있는지 몰라 불안합니다. 올해 10월 발표된 일본 조사에서는 보호자 95%가 이럴 때 불안하다고 답했습니다.</p><h2 id="_6p-또리는-재난문자를-아이-눈높이로-바꿔요" tabindex="-1">6p 또리는 재난문자를 아이 눈높이로 바꿔요 <a class="header-anchor" href="#_6p-또리는-재난문자를-아이-눈높이로-바꿔요" aria-label="Permalink to &quot;6p 또리는 재난문자를 아이 눈높이로 바꿔요&quot;">​</a></h2><p>또리는 이 세 가지 과정을 모두 채워 줍니다.</p><p>재난문자를 아이가 이해할 수 있는 짧고 쉬운 문장으로 풀어 줍니다.</p><p>문제 상황을 인지한 아이가 해야 할 행동을 알려 줍니다.</p><p>이후 아이가 &#39;괜찮아요&#39;나 &#39;도와줘요&#39;를 누르면 보호자에게 위치와 상황을 바로 알려 줍니다. 아이와 부모 모두 서로의 안전을 확인할 수 있습니다.</p><h2 id="_7p-아이-화면-약-40초" tabindex="-1">7p 아이 화면 (약 40초) <a class="header-anchor" href="#_7p-아이-화면-약-40초" aria-label="Permalink to &quot;7p 아이 화면 (약 40초)&quot;">​</a></h2><p>실제 아이 화면입니다. 재난문자가 오면 또또가 쉬운 말로 바로 알려 줍니다. 아래 &#39;따라 해요&#39; 카드를 하나씩 눌러 완료합니다.</p><p>그리고 버튼 하나로 응답합니다. &#39;도와줘요&#39;를 누르면 위치가 보호자에게 가고, 119로 바로 전화할 수 있습니다. &#39;괜찮아요&#39;를 누르면 보호자에게 바로 전해집니다. 대피소 탭에서는 가까운 대피소를 지도로 보여 줍니다.</p><h2 id="_8p-보호자-화면-약-40초" tabindex="-1">8p 보호자 화면 (약 40초) <a class="header-anchor" href="#_8p-보호자-화면-약-40초" aria-label="Permalink to &quot;8p 보호자 화면 (약 40초)&quot;">​</a></h2><p>보호자 화면은 홈 카드 하나로 아이 상태를 보여 줍니다. 평소에는 &#39;대기&#39;, 재난문자가 오면 &#39;응답 대기&#39;, 아이가 괜찮다고 하면 &#39;안전&#39;, 도와달라고 하면 &#39;긴급&#39;으로 바뀌고 아이 위치를 함께 보여 줍니다.</p><p>새로고침하지 않아도 바로 바뀌고, 아이가 응답하지 않으면 보호자에게 다시 알립니다. 기록 탭에서는 지난 알림과 응답을, 대피소 탭에서는 아이 동네 대피소를 볼 수 있습니다.</p><h2 id="_9p-재난이-오기-전에-미리-익혀요-약-40초" tabindex="-1">9p 재난이 오기 전에 미리 익혀요 (약 40초) <a class="header-anchor" href="#_9p-재난이-오기-전에-미리-익혀요-약-40초" aria-label="Permalink to &quot;9p 재난이 오기 전에 미리 익혀요 (약 40초)&quot;">​</a></h2><p>재난은 갑자기 오기 때문에 평소에 미리 익혀 두는 것이 중요합니다. 아이는 재난 종류를 골라 레슨을 하나씩 열고, OX, 객관식, 순서 맞히기 퀴즈를 풉니다. 레슨을 마치면 배지를 받습니다.</p><p>궁금한 것이 생기면 &#39;또또에게 묻기&#39;로 AI에게 물어볼 수 있습니다. 그리고 실제 재난 알림이 오면 학습은 잠깁니다. 퀴즈나 배지보다 지금 해야 할 행동을 먼저 보여 주기 위해서입니다.</p><p>이어서 이 화면들이 어떻게 만들어졌는지, 기술 구성은 OOO님이 설명해 드리겠습니다.</p><hr><h2 id="발표-자료를-고친-과정" tabindex="-1">발표 자료를 고친 과정 <a class="header-anchor" href="#발표-자료를-고친-과정" aria-label="Permalink to &quot;발표 자료를 고친 과정&quot;">​</a></h2><ul><li>3쪽 예시 문자 오타 &quot;참수&quot;를 &quot;침수&quot;로 고쳤다.</li><li>4쪽(일본 사례)을 새로 만들었다. 처음에는 3쪽 아래에 한 줄로 넣었다가 정보가 많아 보여서 따로 뺐다. &quot;피난 권고 vs 피난 지시&quot; 카드도 넣어 봤지만 어수선해서, 설명 문장 안에서 두 말만 굵게 강조했다.</li><li>5쪽 제목 &quot;끊겨 있어요&quot;가 추상적이라 &quot;빠져 있어요&quot;로 바꿨다(&quot;결여&quot;는 한자어라 뺐다). 부모 이야기는 따로 상자로 넣었더니 세 가지 흐름이 끊겨서, &quot;3. 연결&quot; 칸 설명 안에 넣었다.</li><li>원래 6쪽 &quot;재난문자가 오면 이렇게 움직여요&quot;(5단계 흐름)는 해결 방법, 아이 화면, 보호자 화면, 기술 구성과 겹쳐서 뺐다. 아이 화면은 시연과 겹치지만 서비스의 핵심 장면이고 시연 사고 대비용이라 남겼다.</li></ul><h2 id="q-a-대비" tabindex="-1">Q&amp;A 대비 <a class="header-anchor" href="#q-a-대비" aria-label="Permalink to &quot;Q&amp;A 대비&quot;">​</a></h2><ul><li><strong>10명 중 2명 미만:</strong> 일본 내각부 2020년 1월 주민 웹 설문(3,078명). 두 말 모두 바르게 안 사람 17.7%, 둘 다 틀린 사람 66.4%. 피난 권고 때 대피하겠다는 26.4%뿐.</li><li><strong>법에서 없앴다:</strong> 2021년 5월 재해대책기본법 개정으로 &quot;피난 권고&quot; 단계를 없애고 &quot;피난 지시&quot;로 합쳤다.</li><li><strong>95%:</strong> 일본 메이코 기주쿠, 2026년 9~10월, 초1~고3 자녀 보호자 1,000명.</li><li><strong>왜 일본 자료:</strong> 한국에는 재난문자 용어 이해도와 부모 불안을 직접 조사한 자료가 거의 없었다. 한국도 권고와 명령을 나눠 쓰고, 방과후 혼자 있는 아이가 다섯 명 중 한 명(약 116만 명)이다.</li><li><strong>또또, 리리 이름:</strong> 서비스 이름 &quot;또리&quot;를 나눠 아이 친구는 또또, 보호자 친구는 리리. (팀이 정한 이유는 따로 확인 필요)</li></ul>',41)])])}const c=a(r,[["render",i]]);export{d as __pageData,c as default};
